  ('en', 'whatsNew.item.taskOutcomes.detail', $json$"Statistics now shows turns per goal, tasks the validator proved, and tokens and money per verified task."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.taskOutcomes.detail', $json$"As Estatísticas mostram turnos por objetivo, tarefas comprovadas pelo validador e tokens e dinheiro por tarefa comprovada."$json$::jsonb),
  ('es', 'whatsNew.item.taskOutcomes.detail', $json$"Las Estadísticas muestran turnos por objetivo, tareas comprobadas por el validador y tokens y dinero por tarea comprobada."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.taskOutcomes.detail', $json$"统计页面现在显示每个目标的轮次、验证器证实的任务，以及每个已验证任务的 token 和金额。"$json$::jsonb),
  ('hi', 'whatsNew.item.taskOutcomes.detail', $json$"आँकड़े अब प्रति लक्ष्य टर्न, सत्यापक द्वारा प्रमाणित कार्य और प्रति सत्यापित कार्य टोकन व धन दिखाते हैं।"$json$::jsonb),
  ('ar', 'whatsNew.item.taskOutcomes.detail', $json$"تعرض الإحصاءات الآن الأدوار لكل هدف، والمهام التي أثبتها المُتحقق، والرموز والمال لكل مهمة مُثبتة."$json$::jsonb),
  ('fr', 'whatsNew.item.taskOutcomes.detail', $json$"Les statistiques affichent les tours par objectif, les tâches prouvées par le validateur, et les tokens et l’argent par tâche vérifiée."$json$::jsonb),
  ('ru', 'whatsNew.item.taskOutcomes.detail', $json$"Статистика показывает ходы на цель, задачи, подтверждённые проверкой, а также токены и деньги на подтверждённую задачу."$json$::jsonb),
  ('ja', 'whatsNew.item.taskOutcomes.detail', $json$"統計に、目標あたりのターン、検証で証明されたタスク、検証済みタスクあたりのトークンと金額が表示されます。"$json$::jsonb),
  ('de', 'whatsNew.item.taskOutcomes.detail', $json$"Die Statistik zeigt Runden pro Ziel, vom Validator belegte Aufgaben sowie Tokens und Geld pro belegter Aufgabe."$json$::jsonb),
