  ('en', 'whatsNew.item.modelPrices.detail', $json$"A price table per model, edited on the site, estimates the money of calls whose tool reported no cost."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.modelPrices.detail', $json$"Uma tabela de preços por modelo, editada no site, estima o dinheiro das chamadas cuja ferramenta não informou o custo."$json$::jsonb),
  ('es', 'whatsNew.item.modelPrices.detail', $json$"Una tabla de precios por modelo, editada en el sitio, estima el dinero de las llamadas cuya herramienta no informó el costo."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.modelPrices.detail', $json$"在网站上编辑的按模型价格表，会估算工具未报告成本的调用金额。"$json$::jsonb),
