  ('ar', 'whatsNew.item.modelPrices.detail', $json$"جدول أسعار لكل نموذج، يُحرَّر على الموقع، يقدّر مال الاستدعاءات التي لم تُبلغ أداتها عن التكلفة."$json$::jsonb),
  ('fr', 'whatsNew.item.modelPrices.detail', $json$"Une grille de prix par modèle, modifiée sur le site, estime l’argent des appels dont l’outil n’a pas indiqué le coût."$json$::jsonb),
  ('ru', 'whatsNew.item.modelPrices.detail', $json$"Таблица цен по моделям, которую правят на сайте, оценивает стоимость вызовов, для которых инструмент не сообщил цену."$json$::jsonb),
  ('ja', 'whatsNew.item.modelPrices.detail', $json$"サイトで編集するモデル別の価格表で、ツールがコストを報告しなかった呼び出しの金額を見積もります。"$json$::jsonb),
  ('de', 'whatsNew.item.modelPrices.detail', $json$"Eine Preistabelle pro Modell, auf der Website gepflegt, schätzt das Geld von Aufrufen, deren Tool keine Kosten gemeldet hat."$json$::jsonb),
  ('en', 'whatsNew.item.savingsBaseline.title', $json$"Savings only with a baseline"$json$::jsonb),
