  ('es', 'admin.error.priceDuplicate', $json$"Este patrón ya tiene precio."$json$::jsonb),
  ('zh-CN', 'admin.error.priceDuplicate', $json$"该模式已有价格。"$json$::jsonb),
  ('hi', 'admin.error.priceDuplicate', $json$"इस पैटर्न का मूल्य पहले से है।"$json$::jsonb),
  ('ar', 'admin.error.priceDuplicate', $json$"هذا النمط له سعر بالفعل."$json$::jsonb),
  ('fr', 'admin.error.priceDuplicate', $json$"Ce motif a déjà un prix."$json$::jsonb),
  ('ru', 'admin.error.priceDuplicate', $json$"У этого шаблона уже есть цена."$json$::jsonb),
  ('ja', 'admin.error.priceDuplicate', $json$"このパターンにはすでに価格があります。"$json$::jsonb),
  ('de', 'admin.error.priceDuplicate', $json$"Dieses Muster hat bereits einen Preis."$json$::jsonb),
